#include <stdio.h>
#include <stdlib.h>

long long mod_pow(long long base, long long exponent, long long modulus) {
    long long result = 1;
    base = base % modulus;
    while (exponent > 0) {
        if (exponent & 1)
            result = (result * base) % modulus;
        exponent = exponent >> 1;
        base = (base * base) % modulus;
    }
    return result;
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        printf("NO_INPUT\n");
        return 0;
    }
    char *endptr;
    long long base = strtoll(argv[1], &endptr, 10);
    long long exponent = strtoll(argv[2], &endptr, 10);
    long long modulus = strtoll(argv[3], &endptr, 10);
    if (exponent < 0) {
        printf("NEGATIVE_EXPONENT\n");
        return 0;
    }
    if (modulus < 1) {
        printf("BAD_MODULUS\n");
        return 0;
    }
    if (modulus > 1000000000) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }
    long long result = mod_pow(base, exponent, modulus);
    printf("result=%lld\n", result);
    return 0;
}
